//! Builds the message catalogue (`styk_core::i18n`) from the committed, language-neutral catalogue files in `locales/`
//! (`index.json` and one `<id>.json` per locale, generated by `cargo xtask locales generate` from today's catalogues and
//! checked by `cargo xtask check` while those exist). The native build reads only these files.
//!
//! Output: `catalogue.bin` in `OUT_DIR`, read in place at run time (no parsing, no allocation). Little-endian `u32`s:
//!
//! ```text
//! magic "STYKCAT1" | keys | locales | the string pool's byte offset in the file
//! key table:    keys × (offset, length) into the string pool, sorted by the key's bytes
//! locale table: locales × (id offset, id length, direction 0 ltr / 1 rtl, entry table offset)
//! entry tables: locales × keys × entry offset (u32::MAX: the locale has no such message)
//! entries:      plain: 0, offset, length | plural: 1, forms, forms × (category offset, length, text offset, length)
//! string pool
//! ```

use std::path::PathBuf;

fn main() {
    let manifest = PathBuf::from(std::env::var_os("CARGO_MANIFEST_DIR").unwrap_or_default());
    let dir = manifest.join("locales");
    println!("cargo:rerun-if-changed={}", dir.display());
    let read = |name: &str| {
        let path = dir.join(name);
        println!("cargo:rerun-if-changed={}", path.display());
        std::fs::read_to_string(&path).unwrap_or_else(|error| panic!("the catalogue file {} cannot be read: {error}", path.display()))
    };
    let index = read("index.json");
    let locales: Vec<(String, String)> = Parser::new(&index).locales();
    assert!(locales.first().is_some_and(|(id, _)| id == "en"), "locales/index.json lists English first");
    let mut catalogues: Vec<Vec<(String, Value)>> = locales.iter().map(|(id, _)| Parser::new(&read(&format!("{id}.json"))).catalogue()).collect();
    let native = manifest.join("native-messages.json");
    println!("cargo:rerun-if-changed={}", native.display());
    let native = std::fs::read_to_string(native).expect("the native message catalogue");
    catalogues[0].extend(Parser::new(&native).catalogue());

    let mut keys: Vec<String> = catalogues.iter().flat_map(|catalogue| catalogue.iter().map(|(key, _)| key.clone())).collect();
    keys.sort();
    keys.dedup();

    let mut pool = Pool::default();
    let key_refs: Vec<(u32, u32)> = keys.iter().map(|key| pool.add(key)).collect();
    let mut entries: Vec<u32> = Vec::new();
    let mut tables: Vec<Vec<u32>> = Vec::new();
    for catalogue in &catalogues {
        let mut table = vec![u32::MAX; keys.len()];
        for (key, value) in catalogue {
            let at = keys.binary_search(key).unwrap_or_else(|_| panic!("{key} is listed"));
            table[at] = entries.len() as u32;
            match value {
                Value::Plain(text) => {
                    let (offset, length) = pool.add(text);
                    entries.extend([0, offset, length]);
                }
                Value::Plural(forms) => {
                    entries.extend([1, forms.len() as u32]);
                    for (category, text) in forms {
                        let (category_offset, category_length) = pool.add(category);
                        let (offset, length) = pool.add(text);
                        entries.extend([category_offset, category_length, offset, length]);
                    }
                }
            }
        }
        tables.push(table);
    }
    let locale_refs: Vec<(u32, u32, u32)> = locales.iter().map(|(id, direction)| {
        let (offset, length) = pool.add(id);
        (offset, length, u32::from(direction == "rtl"))
    }).collect();

    // Offsets are in u32 units from the start of the u32 area (after the magic), except string pool offsets, in bytes.
    let header = 3u32;
    let key_table = header;
    let locale_table = key_table + 2 * keys.len() as u32;
    let entry_tables = locale_table + 4 * locales.len() as u32;
    let entry_area = entry_tables + (keys.len() * locales.len()) as u32;
    let mut words: Vec<u32> = vec![keys.len() as u32, locales.len() as u32, 0];
    for (offset, length) in &key_refs {
        words.extend([*offset, *length]);
    }
    for (index, (offset, length, rtl)) in locale_refs.iter().enumerate() {
        words.extend([*offset, *length, *rtl, entry_tables + (index * keys.len()) as u32]);
    }
    for table in &tables {
        words.extend(table.iter().map(|entry| if *entry == u32::MAX { u32::MAX } else { entry_area + entry }));
    }
    words.extend(&entries);
    words[2] = (8 + 4 * words.len()) as u32;
    let mut out = b"STYKCAT1".to_vec();
    for word in &words {
        out.extend(word.to_le_bytes());
    }
    out.extend(&pool.bytes);
    let target = PathBuf::from(std::env::var_os("OUT_DIR").unwrap_or_default()).join("catalogue.bin");
    std::fs::write(&target, out).unwrap_or_else(|error| panic!("{} cannot be written: {error}", target.display()));
}

/// The string pool: every string once, by value.
#[derive(Default)]
struct Pool {
    bytes: Vec<u8>,
    seen: std::collections::HashMap<String, (u32, u32)>,
}

impl Pool {
    fn add(&mut self, text: &str) -> (u32, u32) {
        if let Some(found) = self.seen.get(text) {
            return *found;
        }
        let at = (self.bytes.len() as u32, text.len() as u32);
        self.bytes.extend(text.as_bytes());
        self.seen.insert(text.to_owned(), at);
        at
    }
}

enum Value {
    Plain(String),
    Plural(Vec<(String, String)>),
}

/// The subset of JSON the catalogue files use: objects of strings and of objects of strings, and the index's array.
struct Parser<'a> {
    bytes: &'a [u8],
    at: usize,
}

impl<'a> Parser<'a> {
    fn new(text: &'a str) -> Parser<'a> {
        Parser { bytes: text.as_bytes(), at: 0 }
    }

    fn fail(&self, what: &str) -> ! {
        panic!("locales: {what} at byte {}", self.at)
    }

    fn space(&mut self) {
        while self.at < self.bytes.len() && self.bytes[self.at].is_ascii_whitespace() {
            self.at += 1;
        }
    }

    fn expect(&mut self, byte: u8) {
        self.space();
        if self.bytes.get(self.at) != Some(&byte) {
            self.fail(&format!("expected `{}`", byte as char));
        }
        self.at += 1;
    }

    fn peek(&mut self) -> u8 {
        self.space();
        self.bytes.get(self.at).copied().unwrap_or(0)
    }

    fn comma(&mut self) {
        if self.peek() == b',' {
            self.at += 1;
        }
    }

    fn string(&mut self) -> String {
        self.expect(b'"');
        let mut out = Vec::new();
        loop {
            let Some(&byte) = self.bytes.get(self.at) else { self.fail("unterminated string") };
            self.at += 1;
            match byte {
                b'"' => break,
                b'\\' => {
                    let Some(&escape) = self.bytes.get(self.at) else { self.fail("unterminated escape") };
                    self.at += 1;
                    let decoded = match escape {
                        b'n' => '\n',
                        b't' => '\t',
                        b'r' => '\r',
                        b'b' => '\u{8}',
                        b'f' => '\u{c}',
                        b'/' => '/',
                        b'\\' => '\\',
                        b'"' => '"',
                        b'u' => {
                            let unit = self.hex4();
                            let scalar = if (0xd800..0xdc00).contains(&unit) {
                                if self.bytes.get(self.at..self.at + 2) != Some(b"\\u") {
                                    self.fail("lone high surrogate");
                                }
                                self.at += 2;
                                let low = self.hex4();
                                0x10000 + ((unit - 0xd800) << 10) + (low - 0xdc00)
                            } else {
                                unit
                            };
                            char::from_u32(scalar).unwrap_or_else(|| self.fail("invalid escape"))
                        }
                        _ => self.fail("unknown escape"),
                    };
                    let mut buffer = [0; 4];
                    out.extend_from_slice(decoded.encode_utf8(&mut buffer).as_bytes());
                }
                _ => out.push(byte),
            }
        }
        String::from_utf8(out).unwrap_or_else(|_| self.fail("invalid UTF-8"))
    }

    fn hex4(&mut self) -> u32 {
        let digits = self.bytes.get(self.at..self.at + 4).unwrap_or_else(|| self.fail("short escape"));
        let digits = std::str::from_utf8(digits).unwrap_or_else(|_| self.fail("bad escape"));
        self.at += 4;
        u32::from_str_radix(digits, 16).unwrap_or_else(|_| self.fail("bad escape"))
    }

    fn pairs(&mut self) -> Vec<(String, String)> {
        let mut pairs = Vec::new();
        self.expect(b'{');
        while self.peek() != b'}' {
            let key = self.string();
            self.expect(b':');
            pairs.push((key, self.string()));
            self.comma();
        }
        self.expect(b'}');
        pairs
    }

    /// `[{"id": ..., "direction": ...}, ...]`.
    fn locales(&mut self) -> Vec<(String, String)> {
        let mut locales = Vec::new();
        self.expect(b'[');
        while self.peek() != b']' {
            let pairs = self.pairs();
            let field = |name: &str| pairs.iter().find(|(key, _)| key == name).map(|(_, value)| value.clone()).unwrap_or_else(|| panic!("locales/index.json: a locale without `{name}`"));
            locales.push((field("id"), field("direction")));
            self.comma();
        }
        self.expect(b']');
        locales
    }

    fn catalogue(&mut self) -> Vec<(String, Value)> {
        let mut entries = Vec::new();
        self.expect(b'{');
        while self.peek() != b'}' {
            let key = self.string();
            self.expect(b':');
            let value = if self.peek() == b'{' { Value::Plural(self.pairs()) } else { Value::Plain(self.string()) };
            entries.push((key, value));
            self.comma();
        }
        self.expect(b'}');
        entries
    }
}
